window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3442b2c854576e11"]={"versions": [{"id": "FIG-3442b2c854576e11", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd TpReception</code>) zur Darstellung des Empfangsablaufs von Transportprotokoll-Nachrichten (LIN TP) innerhalb der AUTOSAR Classic Platform. Das Diagramm spezifiziert die Interaktion zwischen dem Betriebssystem-Kontext bzw. Task-Scheduler, dem LIN-Interface (<code>LinIf</code>) und dem PDU-Router (<code>PduR</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten und Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>BSW Task (OS task or cyclic call)</code>: Auslöser der zyklischen Abarbeitung.</li>\n<li><code>PduR::PduR</code>: PDU-Router-Modul als Empfänger von Pufferanfragen und Empfangsmeldungen.</li>\n<li><code>LinIf::LinIf</code>: LIN-Interface-Modul, das den Empfang steuert und puffert.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Funktionsaufrufe:</p>\n<ul class=\"fig-list\">\n<li><code>LinIf_MainFunction()</code>: Zyklische Hauptfunktion des LIN-Interfaces.</li>\n<li><code>PduR_LinTpProvideRxBuffer(LinTpRxPduId,TpSduLength,PduInfoPtr) :BufReq_ReturnType</code>: PduR-Funktion zur Anforderung und Bereitstellung eines Empfangspuffers.</li>\n<li><code>PduR_LinTpRxIndication(LinTpRxPduId,Result)</code>: PduR-Funktion zur Benachrichtigung über den Abschluss des Empfangs.</li>\n<li><code>CopyBuffer</code>: Interne Selbstaufruf-Aktion von <code>LinIf</code> zum Kopieren empfangener Daten in den bereitgestellten Puffer.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Gesamtablauf wird durch ein kombiniertes Fragment <code>alt TP status</code> in drei alternative Phasen unterteilt:</p>\n<ol class=\"fig-list\">\n<li><code>[TP reception message start / buffer request]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>BSW Task</code> ruft synchron <code>LinIf_MainFunction()</code> auf.</li>\n<li><code>LinIf</code> ruft synchron <code>PduR_LinTpProvideRxBuffer(LinTpRxPduId,TpSduLength,PduInfoPtr)</code> am <code>PduR</code> auf, um den Empfangspuffer anzufordern, und empfängt den Rückgabewert <code>:BufReq_ReturnType</code>.</li>\n<li><code>LinIf</code> führt die interne Operation <code>CopyBuffer</code> aus.</li>\n<li>Rückkehr der Steuerung an den <code>BSW Task</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>[TP message reception]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nachfolgender Aufruf von <code>LinIf_MainFunction()</code> durch den <code>BSW Task</code>.</li>\n<li><code>LinIf</code> verarbeitet die empfangenen Datenbytes über die interne Aktion <code>CopyBuffer</code>.</li>\n<li>Rückkehr der Steuerung an den <code>BSW Task</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>[TP message finish]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Erneuter Aufruf von <code>LinIf_MainFunction()</code> durch den <code>BSW Task</code>.</li>\n<li><code>LinIf</code> schließt das Einlesen über <code>CopyBuffer</code> ab.</li>\n<li><code>LinIf</code> meldet den Abschluss der Übertragung synchron via <code>PduR_LinTpRxIndication(LinTpRxPduId,Result)</code> an <code>PduR</code>.</li>\n<li>Rückkehr der Bestätigung an <code>LinIf</code> und anschließende Rückkehr an den <code>BSW Task</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht das Polling- und Event-Modell des AUTOSAR LIN Transport Protocols über zyklische Hauptfunktionen:</p>\n<ul class=\"fig-list\">\n<li>Der LIN-TP-Empfang erfolgt schrittweise im Kontext der periodischen <code>LinIf_MainFunction()</code>.</li>\n<li>Die Pufferanforderung (<code>ProvideRxBuffer</code>) erfolgt zu Beginn der Nachricht, während Daten kontinuierlich via <code>CopyBuffer</code> übernommen werden.</li>\n<li>Die Statusmeldung an den PDU-Router (<code>RxIndication</code>) signalisiert den finalen Status (<code>Result</code>) nach Empfang der vollständigen TP-Botschaft.</li>\n</ul>"}, {"id": "FIG-2d67db7836582178", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd TpReception</code>) zur Darstellung des Empfangsablaufs von Transportprotokoll-Nachrichten (LIN TP) innerhalb der AUTOSAR Classic Platform. Das Diagramm spezifiziert die Interaktion zwischen dem Betriebssystem-Kontext bzw. Task-Scheduler, dem LIN-Interface (<code>LinIf</code>) und dem PDU-Router (<code>PduR</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten und Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>BSW Task (OS task or cyclic call)</code>: Auslöser der zyklischen Abarbeitung.</li>\n<li><code>«module» PduR::PduR</code>: Als Modul typisierter PDU-Router als Empfänger von Pufferanfragen und Empfangsmeldungen.</li>\n<li><code>«module» LinIf::LinIf</code>: Als Modul typisiertes LIN-Interface, das den Empfang steuert und puffert.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Funktionsaufrufe:</p>\n<ul class=\"fig-list\">\n<li><code>LinIf_MainFunction()</code>: Zyklische Hauptfunktion des LIN-Interfaces.</li>\n<li><code>PduR_LinTpProvideRxBuffer(LinTpRxPduId, TpSduLength, PduInfoPtr) :BufReq_ReturnType</code>: PduR-Funktion zur Anforderung und Bereitstellung eines Empfangspuffers.</li>\n<li><code>PduR_LinTpRxIndication(LinTpRxPduId,Result)</code>: PduR-Funktion zur Benachrichtigung über den Abschluss des Empfangs.</li>\n<li><code>CopyBuffer</code>: Interne Selbstaufruf-Aktion von <code>LinIf</code> zum Kopieren empfangener Daten in den bereitgestellten Puffer.</li>\n<li>Notizblock mit Metadaten (<code>Status:Proposed by WPII-2.1.1 as per LinIf SWS 1.1.2</code>, <code>Description:</code>, <code>Comments:</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Gesamtablauf wird durch ein kombiniertes Fragment <code>alt TP status</code> in drei alternative Phasen unterteilt:</p>\n<ol class=\"fig-list\">\n<li><code>[TP reception message start / buffer request]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>BSW Task</code> ruft synchron <code>LinIf_MainFunction()</code> auf.</li>\n<li><code>LinIf</code> ruft synchron <code>PduR_LinTpProvideRxBuffer(LinTpRxPduId,TpSduLength,PduInfoPtr)</code> am <code>PduR</code> auf, um den Empfangspuffer anzufordern, und empfängt den Rückgabewert <code>:BufReq_ReturnType</code>.</li>\n<li><code>LinIf</code> führt die interne Operation <code>CopyBuffer</code> aus.</li>\n<li>Rückkehr der Steuerung an den <code>BSW Task</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>[TP message reception]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nachfolgender Aufruf von <code>LinIf_MainFunction()</code> durch den <code>BSW Task</code>.</li>\n<li><code>LinIf</code> verarbeitet die empfangenen Datenbytes über die interne Aktion <code>CopyBuffer</code>.</li>\n<li>Rückkehr der Steuerung an den <code>BSW Task</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>[TP message finish]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Erneuter Aufruf von <code>LinIf_MainFunction()</code> durch den <code>BSW Task</code>.</li>\n<li><code>LinIf</code> schließt das Einlesen über <code>CopyBuffer</code> ab.</li>\n<li><code>LinIf</code> meldet den Abschluss der Übertragung synchron via <code>PduR_LinTpRxIndication(LinTpRxPduId,Result)</code> an <code>PduR</code>.</li>\n<li>Rückkehr der Bestätigung an <code>LinIf</code> und anschließende Rückkehr an den <code>BSW Task</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht das Polling- und Event-Modell des AUTOSAR LIN Transport Protocols über zyklische Hauptfunktionen:</p>\n<ul class=\"fig-list\">\n<li>Der LIN-TP-Empfang erfolgt schrittweise im Kontext der periodischen <code>LinIf_MainFunction()</code>.</li>\n<li>Die Pufferanforderung (<code>ProvideRxBuffer</code>) erfolgt zu Beginn der Nachricht, während Daten kontinuierlich via <code>CopyBuffer</code> übernommen werden.</li>\n<li>Die Statusmeldung an den PDU-Router (<code>RxIndication</code>) signalisiert den finalen Status (<code>Result</code>) nach Empfang der vollständigen TP-Botschaft.</li>\n</ul>"}], "trans": [{"from": "FIG-3442b2c854576e11", "to": "FIG-2d67db7836582178", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Lifeline-Header: Die BSW-Module <code>PduR::PduR</code> und <code>LinIf::LinIf</code> sind mit dem Stereotyp <code>«module»</code> versehen.</li>\n<li>Rückkehrpfeile: Die Beschriftungen <code>PduR_LinTpProvideRxBuffer</code>, <code>PduR_LinTpRxIndication</code> und dreimal <code>LinIf_MainFunction</code> an den gestrichelten Return-Nachrichten wurden entfernt.</li>\n<li>Metadaten-Notizblock: Ein Notizfeld mit den Feldern <code>Status:Proposed by WPII-2.1.1 as per LinIf SWS 1.1.2</code>, <code>Description:</code> und <code>Comments:</code> wurde links unten ergänzt.</li>\n</ul>"}]};
